INSERT INTO listings (id, slug, host_id, status, review_note, title_ar, title_en, description_ar, description_en, city_slug, district_ar, district_en, address, lat, lng, bedrooms, beds, bathrooms, max_guests, area_sqm, amenities, base_price, weekend_price, cleaning_fee, min_nights, max_nights, weekly_discount, monthly_discount, cancellation_policy, check_in_time, check_out_time, house_rules_ar, house_rules_en, featured, unit_type, paused, is_demo, created_at, updated_at) VALUES (16, 'riyadh-narjis-duplex', 4, 'approved', NULL, 'دوبلكس حديث في النرجس', 'Modern duplex in Al Narjis', 'دوبلكس بثلاث غرف وتصميم مفتوح وجلسة سطح، مع موقفين. مناسب للعائلات والإقامات الطويلة.', 'A three-bedroom duplex with open-plan design, rooftop seating and two parking spaces. Ideal for families and longer stays.', 'riyadh', 'النرجس', 'Al Narjis', 'عنوان تجريبي — النرجس، الرياض', 24.8336, 46.6453, 3, 4, 3, 6, 210, '["wifi","parking","ac","kitchen","washer","tv","family","garden","workspace"]', 72000, 82000, 10000, 1, 30, 12, 25, 'moderate', '15:00', '12:00', '• يُمنع التدخين داخل الشقة.
